package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="contribuicao_movimentacao",schema="adm_eclesial") public class ContribuicaoMovimentacao { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="contribuicao_id",nullable=false) Long contribuicaoId; @Column(name="movimentacao_financeira_id",nullable=false) Long movimentacaoFinanceiraId; @Column(nullable=false,precision=15,scale=2) BigDecimal valor; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getContribuicaoId(){return contribuicaoId;} public Long getMovimentacaoFinanceiraId(){return movimentacaoFinanceiraId;} public BigDecimal getValor(){return valor;} public void setContribuicaoId(Long v){contribuicaoId=v;} public void setMovimentacaoFinanceiraId(Long v){movimentacaoFinanceiraId=v;} public void setValor(BigDecimal v){valor=v;} }